using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using Xunit;

namespace Cybersole.Tests;

/// <summary>
/// R1041: docs/CORE_COVERAGE.md is generated by tools/core_coverage.py, and a generated file still rots if nothing
/// checks that it was regenerated. R1030 recorded the append-only version of that failure; this is the generated
/// version, and the guard is the same idea -- a number in a document has to agree with the thing that produced it.
///
/// <para>
/// The criterion (f) table has two halves. The replica side is computed from the flow files, so a mismatch here means
/// the document is stale. The original side is deliberately <c>Unknown</c> with the missing artefact named, because
/// R1040 probed three shapes for a store catalogue and found none; a guard asserts that section still says so rather
/// than quietly drifting into a claim.
/// </para>
/// </summary>
public sealed class CoreCoverageDocumentTests
{
    private static string Root()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "Cybersole.sln"))) dir = dir.Parent;
        return dir!.FullName;
    }

    private static string Doc() => File.ReadAllText(Path.Combine(Root(), "docs", "CORE_COVERAGE.md"));

    /// <summary>The flow count in the table equals the number of flow files on disk.</summary>
    [Fact]
    public void TheFlowCountMatchesTheTree()
    {
        var flowsDir = Path.Combine(Root(), "src", "Cybersole.Stores", "Flows");
        var onDisk = Directory.EnumerateFiles(flowsDir, "*.cs")
            .Count(p => File.ReadAllText(p).Contains("public override", StringComparison.Ordinal));

        var m = Regex.Match(Doc(), @"\| flow 文件 \| (\d+) \|");
        Assert.True(m.Success, "the flow-count row is gone from CORE_COVERAGE.md");

        // The generator counts files that declare at least one override, which is the same predicate used here.
        Assert.Equal(onDisk, int.Parse(m.Groups[1].Value));
    }

    /// <summary>The original's store list is still recorded as unknown, with what is missing named.</summary>
    [Fact]
    public void TheOriginalStoreListIsStillUnknown()
    {
        var doc = Doc();
        Assert.Contains("Unknown", doc, StringComparison.Ordinal);
        Assert.Contains("connect/app", doc, StringComparison.Ordinal);
    }

    /// <summary>And the three probe shapes that came back empty are recorded, so nobody repeats them.</summary>
    [Fact]
    public void TheEmptyProbesAreRecorded()
    {
        var doc = Doc();
        Assert.Contains("FarfetchFlow", doc, StringComparison.Ordinal);
        Assert.Contains("TPL Dataflow", doc, StringComparison.Ordinal);
    }

    /// <summary>The document states it is generated, so a reader does not edit it by hand.</summary>
    [Fact]
    public void TheDocumentSaysItIsGenerated()
    {
        Assert.Contains("core_coverage.py", Doc(), StringComparison.Ordinal);
    }
}
